#!/usr/bin/env python3
"""Curated peoples-languages records: how language families spread (with competing homeland theories),
scripts and where they came from, when languages are first written and when they die, script reforms,
and what ancient DNA showed about who moved where.

Usage: python3 ingest/peoples-languages/curated.py
Writes data/peoples-languages/{spread,scripts,events,findings}.jsonl. Everything here is model-written
from the works cited on each record, so it is `draft` until the judge checks it.
Migrations already in data/economy-trade (Bantu, Austronesian, Yamnaya, Norse...) are linked, not repeated.
"""
import json, os, re, sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from sources import src  # noqa: E402

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
OUT = os.path.join(ROOT, 'data', 'peoples-languages')
L = ['language']
LP = ['language', 'population']


def slug(s):
    return re.sub(r'[^a-z0-9]+', '_', s.lower()).strip('_')


def H(view, school, lat, lon, start, strength, claim, pro, con, *keys):
    return {'view': view, 'school': school, 'lat': lat, 'lon': lon, 'start': start, 'strength': strength,
            'claim': claim, 'for': pro, 'against': con, 'sources': src(*keys)}


def st(year, lat, lon, name, note):
    return {'year': year, 'lat': lat, 'lon': lon, 'name': name, 'note': note}


