def write(name, recs):
    with open(os.path.join(OUT, name), 'w', encoding='utf-8') as fh:
        for r in recs:
            fh.write(json.dumps({k: v for k, v in r.items() if v is not None and v != [] and v != ''}, ensure_ascii=False) + '\n')
    print(name, len(recs))


spread = []
for d in SPREAD:
    fam = d['lang']
    lead = d['hyp'][0]
    srcs = [s for h in d['hyp'] for s in h['sources']]
    srcs = [s for i, s in enumerate(srcs) if s not in srcs[:i]]
    rid = 'event:spread_' + slug(d['name'].replace(' spread', '').replace('(Thule) ', ''))
    spread.append({'id': rid, 'kind': 'event', 'subtype': 'language_spread', 'name': d['name'], 'lenses': LP,
                   'language': 'lang:' + fam, 'start': d['start'], 'start_approx': True, 'start_range': d.get('start_range'),
                   'end': d.get('end'), 'lat': lead['lat'], 'lon': lead['lon'], 'what': d['what'], 'why': d['why'],
                   'hypotheses': d['hyp'], 'stages': d['stages'], 'links': ['lang:' + fam] + d.get('links', []),
                   'sources': srcs, 'status': 'draft'})
write('spread.jsonl', spread)

scripts, rels = [], []
for (sl, name, iso, s, e, lat, lon, place, parent, kind, what, why, keys) in SCRIPTS:
    scripts.append({'id': 'script:' + sl, 'kind': 'script', 'name': name, 'subtype': kind, 'lenses': ['language', 'ideas'],
                    'start': s, 'start_approx': True, 'end': e, 'lat': lat, 'lon': lon, 'origin': place,
                    'ext': {'iso15924': iso} if iso else None, 'what': what, 'why': why,
                    'sources': src(*keys) + ([src('iso15924')[0]] if iso else []), 'status': 'draft'})
    if parent:
        rels.append({'id': f'rel:script_{sl}_from_{parent}', 'kind': 'relation', 'type': 'derived_from',
                     'from': 'script:' + sl, 'to': 'script:' + parent, 'start': s, 'lenses': ['language'],
                     'sources': src(*keys), 'status': 'draft'})
write('scripts.jsonl', scripts + rels)

ev = []
for (g, name, s, e, lat, lon, what, why, keys) in ATTESTED:
    ev.append({'id': 'event:written_' + slug(name), 'kind': 'event', 'subtype': 'attestation', 'name': f'{name} written',
               'lenses': L, 'language': 'lang:' + g, 'start': s, 'start_approx': True, 'end': e, 'lat': lat, 'lon': lon,
               'what': what, 'why': why, 'links': ['lang:' + g], 'sources': src(*keys), 'status': 'draft'})
for (g, name, y, lat, lon, what, why, keys) in DEATHS:
    ev.append({'id': 'event:language_death_' + slug(name), 'kind': 'event', 'subtype': 'language_death',
               'name': f'Death of {name}' if '(' not in name else name, 'lenses': L, 'language': 'lang:' + g,
               'start': y, 'lat': lat, 'lon': lon, 'what': what, 'why': why, 'links': ['lang:' + g],
               'sources': src(*keys), 'status': 'draft'})
for (sl, name, y, lat, lon, what, why, keys, script) in REFORMS:
    ev.append({'id': 'event:script_' + sl, 'kind': 'event', 'subtype': 'script_reform', 'name': name, 'lenses': L,
               'start': y, 'lat': lat, 'lon': lon, 'what': what, 'why': why, 'links': [script], 'sources': src(*keys), 'status': 'draft'})
write('events.jsonl', ev)

fi = []
for (sl, name, s, e, lat, lon, what, why, share, links, keys) in FINDINGS:
    fi.append({'id': 'event:adna_' + sl, 'kind': 'event', 'subtype': 'genetic_finding', 'name': name, 'lenses': LP,
               'start': s, 'start_approx': True, 'end': e, 'lat': lat, 'lon': lon, 'what': what, 'why': why,
               'ancestry_share': share, 'links': links, 'sources': src(*keys), 'status': 'draft'})
write('findings.jsonl', fi)
